'use strict';
// Design-only finance workspace. All amounts, routes and addresses are synthetic.
const financeLabels={overview:['Обзор финансов','Finance overview'],movements:['Движение средств','Money movements'],partners:['Партнёры','Partners'],payouts:['Выплаты','Payouts'],own:['Собственные средства','Own funds'],settings:['Настройки финансов','Finance settings']};
const financePolicyKinds={tariff:['Тариф сервиса','Service tariff'],vip:['VIP пользователя','User VIP'],partner:['Денежное правило партнёра','Partner monetary rule'],protection:['Защита выплат','Payout safeguards'],source:['Собственный источник','Own funding source'],address:['Реквизиты партнёра','Partner recipient details']};
const financePartners=[{id:'P-DEMO-01',name:'Demo Polaris',venue:'Polymarket',debt:120,pending:15,address:'0x1111111111111111111111111111111111111111'},{id:'P-DEMO-02',name:'Demo Aurora',venue:'Limitless',debt:80,pending:0,address:'0x2222222222222222222222222222222222222222'}];
function newFinance(){return{view:'overview',scenario:'alpha',venue:'all',from:'2026-10-17',to:'2026-10-23',query:'',status:'all',partnerId:'P-DEMO-01',payoutId:null,payouts:[],notice:null,error:null,proof:null,handoff:false,resume:'finance',outcome:'success',block:'none',eligible:190,otherReserves:0,operational:20,threshold:150,sourceActive:true,sourceVersion:1,policyKind:'tariff',policies:{},clockOffset:0,events:[],showReceipts:true,showExpenses:true};}
let finance=newFinance();
const financeAccess=()=>({read:!!account?.logged&&actor().owner,write:!!account?.logged&&actor().owner});
const financeText=pair=>pl(...pair);
const fbtn=(ru,en,a,extra='',primary=false)=>`<button type="button" class="btn${primary?' primary':''}" data-finance="${a}" ${extra}>${pl(ru,en)}</button>`;
const fmoney=v=>new Intl.NumberFormat(state.locale==='ru'?'ru-RU':'en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v)+' USDT';
const fsource=()=>finance.partnerId==='P-DEMO-02'?'SRC-DEMO-LL':'SRC-DEMO-PM';
const fpartner=()=>financePartners.find(p=>p.id===finance.partnerId)||financePartners[0];
const fpayout=()=>finance.payouts.find(p=>p.id===finance.payoutId);
const fpaid=()=>finance.scenario==='future';
const financeDates=['2026-10-17','2026-10-18','2026-10-19','2026-10-20','2026-10-21','2026-10-22','2026-10-23'];
function financeEntries(){const entries=fpaid()?[['REV-01','2026-10-18','Polymarket',['Поступление дохода','Revenue receipt'],40,'receipt'],['REV-02','2026-10-20','Polymarket',['Поступление дохода','Revenue receipt'],60,'receipt'],['REV-03','2026-10-21','Limitless',['Поступление дохода','Revenue receipt'],30,'receipt'],['REV-04','2026-10-23','Limitless',['Поступление дохода','Revenue receipt'],50,'receipt']]:[['FUND-01','2026-10-17','Polymarket',['Финансирование владельца','Owner funding'],200,'funding']];entries.push(['COST-01','2026-10-19','Polymarket',['Расход сервиса','Service expense'],-5,'expense'],['COST-02','2026-10-22','Polymarket',['Расход сервиса','Service expense'],-5,'expense']);return entries;}
function financeSelectedEntries(){return financeEntries().filter(x=>x[1]>=finance.from&&x[1]<=finance.to&&(finance.venue==='all'||x[2]===finance.venue)&&(!finance.query||x.join(' ').toLowerCase().includes(finance.query.toLowerCase())));}
const financePartnerIncluded=p=>(finance.venue==='all'||p.venue===finance.venue)&&[p.id,p.name].join(' ').toLowerCase().includes(finance.query.toLowerCase());

const fpolicyKey=()=>finance.policyKind==='source'&&finance.sourceTarget&&finance.sourceTarget!=='SRC-DEMO-PM'?'source:'+finance.sourceTarget:['partner','address'].includes(finance.policyKind)?finance.policyKind+':'+finance.partnerId:finance.policyKind==='vip'?'vip:'+(finance.vipUserId||state.userId):finance.policyKind;
const fpolicy=()=>finance.policies[fpolicyKey()]??(finance.policies[fpolicyKey()]={kind:finance.policyKind,subject:['partner','address'].includes(finance.policyKind)?finance.partnerId:finance.policyKind==='vip'?(finance.vipUserId||state.userId):finance.policyKind==='source'?(finance.sourceTarget||'SRC-DEMO-PM'):'Shadow',venue:['partner','address'].includes(finance.policyKind)?fpartner().venue:'all',version:1,status:'draft',value:'',reason:'',effective:'2026-11-01T00:00',approvals:[],history:[],checked:false,activeAt:null});
const fnow=()=>Date.now()+finance.clockOffset;
const financeUTC=v=>new Date(/(?:Z|[+-]\d{2}:\d{2})$/.test(v)?v:v+'Z').getTime();
function financeCurrentPolicy(key){const p=finance.policies[key];return p?.history.filter(h=>h.status==='published'&&financeUTC(h.effective)<=fnow()).sort((a,b)=>b.version-a.version)[0]||null;}
function financeRecipient(partner){const p=finance.policies['address:'+partner.id],v=p?.activeVersion;return {address:v?.value||partner.address,version:v?.version||1,changed:!!v,network:v?.extra?.network||'Demo network',asset:v?.extra?.asset||'USDT / DEMO-CONTRACT'};}
function financeRecipientReady(p){const proposal=finance.policies['address:'+p.partner],r=financeRecipient(financePartners.find(x=>x.id===p.partner));return r.network==='Demo network'&&r.asset==='USDT / DEMO-CONTRACT'&&!['waiting','cooldown'].includes(proposal?.status)&&r.address===p.address&&r.version===p.recipientVersion&&r.network===p.network&&r.asset===p.asset;}
const fsettled=source=>finance.payouts.filter(p=>p.source===source&&p.status==='confirmed').reduce((n,p)=>n+p.amount+p.fee,0);
const fpolicyDual=kind=>['partner','protection','source','address'].includes(kind);
function flog(ru,en){finance.events.push({who:actor().id,label:[ru,en],time:new Date().toISOString()});}
function financeSourceConfig(){return finance.policies.source?.history.at(-1)?.extra||null;}
function fblocked(source='SRC-DEMO-PM'){const c=financeSourceConfig();return finance.block!=='none'||(source==='SRC-DEMO-PM'&&(!finance.sourceActive||c&&(c.purpose!=='payout'||c.network!=='Demo network'||c.asset!=='USDT / DEMO-CONTRACT')));}
function freserved(source,except){return finance.payouts.filter(p=>p.source===source&&p.id!==except&&['prepared','waiting','approved','unknown'].includes(p.status)).reduce((n,p)=>n+p.amount+p.fee,0);}
function ffree(source,except){const eligible=source==='SRC-DEMO-PM'?finance.eligible+financeFunded():120,other=source==='SRC-DEMO-PM'?finance.otherReserves:0;return Math.max(0,eligible-fsettled(source)-other-finance.operational-freserved(source,except));}
function fdigest(x){return JSON.stringify([x.id,x.partner,x.amount,x.address,x.source,x.sourceVersion,x.fee,x.required,x.ruleVersion,finance.block,x.source==='SRC-DEMO-PM'?finance.sourceActive:true,x.recipientVersion,x.network,x.asset,financeSafeguards(x.amount,x.partner,x.source,x.recipientVersion,x.id),finance.policies['address:'+x.partner]?fpolicyDigest(finance.policies['address:'+x.partner]):'recipient-v1']);}
function fapprovals(x){return x.approvals.filter(a=>a.digest===fdigest(x)&&a.expires>Date.now());}
function fpolicyDigest(x){return JSON.stringify([x.kind,x.subject,x.venue,x.version,x.value,x.reason,x.effective,x.extra,x.tiers]);}
function fproofValid(digest){return finance.proof?.id===actor().id&&finance.proof.digest===digest&&finance.proof.expires>Date.now();}
function fcheckPolicy(x){return financeTiersValid(x)&&financeExtraValid(x)&&!!x.reason.trim()&&!!x.effective&&Number.isFinite(financeUTC(x.effective))&&(x.kind==='address'?/^0x[a-fA-F0-9]{40}$/.test(x.value):x.kind==='source'?x.value.trim().length>=3:Number.isFinite(Number(x.value))&&x.value!==''&&Number(x.value)>=0&&Number(x.value)<=(x.kind==='protection'?1000000000:100));}
function financeSafeguards(amount,partner,source,recipientVersion=1,exceptId=null){const p=financeCurrentPolicy('protection');if(!p)return {required:amount>finance.threshold?2:1,blocked:false,version:'GUARD-DEMO-v1'};const e=p.extra,today=new Date(fnow()).toISOString().slice(0,10);const sent=finance.payouts.filter(x=>x.id!==exceptId&&x.status!=='failed'&&(x.status!=='confirmed'||(x.completedAt||'').slice(0,10)===today));const daily=sent.reduce((n,x)=>n+x.amount,0)+amount,perPartner=sent.filter(x=>x.partner===partner).reduce((n,x)=>n+x.amount,0)+amount,perSource=sent.filter(x=>x.source===source).reduce((n,x)=>n+x.amount,0)+amount;return {blocked:amount>Number(e.hardMax),required:amount>Number(p.value)||daily>Number(e.daily)||perPartner>Number(e.perPartner)||perSource>Number(e.perSource)||(!!finance.policies['address:'+partner]?.activeVersion&&amount>Number(e.newAddress))?2:1,version:'GUARD-v'+p.version};}
function financePrepare(){if(!financeAccess().write||!fpaid()||fblocked(fsource()))return false;const partner=fpartner();const existing=finance.payouts.find(p=>p.partner===partner.id&&p.status!=='failed');if(existing){finance.payoutId=existing.id;navigate('payout');return true;}const route=finance.policies['address:'+partner.id];if(route&&['waiting','cooldown'].includes(route.status)){finance.error=['Новые реквизиты ещё недоступны. Не переключаем выплату на старый адрес автоматически.','New recipient details are not available yet. No automatic fallback to the old address.'];return false;}const source=fsource();if(ffree(source)<partner.debt+0.5){finance.error=['На весь долг и комиссию не хватает средств. Выплата целиком ожидает пополнения.','Insufficient funds for the entire debt and fee. The full payout waits for funding.'];return false;}const recipient=financeRecipient(partner);if(recipient.network!=='Demo network'||recipient.asset!=='USDT / DEMO-CONTRACT'){finance.error=['Для этой сети и актива нет зарегистрированного маршрута выплат.','No registered payout route for this network and asset.'];return false;}const guard=financeSafeguards(partner.debt,partner.id,source,recipient.version);if(guard.blocked){finance.error=['Жёсткий максимум запрещает выплату. Два согласия не отменяют этот запрет.','The hard maximum blocks this payout. Two approvals do not override it.'];return false;}const p={id:'PAY-DEMO-'+(finance.payouts.length+1),partner:partner.id,venue:partner.venue,amount:partner.debt,fee:0.5,address:recipient.address,recipientVersion:recipient.version,network:recipient.network,asset:recipient.asset,source,sourceVersion:source==='SRC-DEMO-PM'?finance.sourceVersion:1,ruleVersion:'PARTNER-DEMO-v1',required:guard.required,guardVersion:guard.version,status:'prepared',approvals:[],external:null};finance.payouts.push(p);finance.payoutId=p.id;finance.proof=null;flog('Создана полная учебная выплата, резерв один','Full synthetic payout prepared, reserved once');navigate('payout');return true;}
function financeApprove(){const p=fpayout();if(p){const g=financeSafeguards(p.amount,p.partner,p.source,p.recipientVersion,p.id);if(g.blocked)return false;p.required=g.required;p.guardVersion=g.version;}if(!financeAccess().write||!p||!financeRecipientReady(p)||fblocked(p.source)||!['prepared','waiting','approved'].includes(p.status)||!fproofValid(fdigest(p))||fapprovals(p).some(a=>a.id===actor().id))return false;p.approvals=fapprovals(p);p.approvals.push({id:actor().id,digest:fdigest(p),expires:Date.now()+600000});finance.proof=null;p.status=p.approvals.length>=p.required?'approved':'waiting';flog('Подтверждена версия '+p.id,'Approved version '+p.id);return true;}
function financeSubmit(){const p=fpayout();if(!financeAccess().write||!p||!financeRecipientReady(p)||!fpaid()||fblocked(p.source)||p.status!=='approved'||financeSafeguards(p.amount,p.partner,p.source,p.recipientVersion,p.id).blocked||p.required<financeSafeguards(p.amount,p.partner,p.source,p.recipientVersion,p.id).required||fapprovals(p).length<p.required||p.sourceVersion!==(p.source==='SRC-DEMO-PM'?finance.sourceVersion:1)||ffree(p.source,p.id)<p.amount+p.fee)return false;p.status=finance.outcome==='success'?'confirmed':finance.outcome==='failure'?'failed':'unknown';p.external=p.status==='confirmed'?'TX-DEMO-'+p.id:null;p.completedAt=p.status==='confirmed'?new Date(fnow()).toISOString():null;if(p.status==='unknown')financeEnsureIncident(p);flog('Учебный исход выплаты: '+p.status,'Synthetic payout outcome: '+p.status);finance.proof=null;return true;}
function financePolicyApprove(){const p=fpolicy(),digest=fpolicyDigest(p);if(!financeAccess().write||!['draft','waiting'].includes(p.status)||!p.checked||!fcheckPolicy(p)||!fproofValid(digest)||p.approvals.some(a=>a.id===actor().id&&a.digest===digest&&a.expires>Date.now()))return false;p.approvals=p.approvals.filter(a=>a.digest===digest&&a.expires>Date.now());p.approvals.push({id:actor().id,digest,issuedAt:fnow(),expires:Date.now()+600000});finance.proof=null;if(p.approvals.length>=(fpolicyDual(p.kind)?2:1)){p.status=p.kind==='address'?'cooldown':'published';p.activeAt=p.kind==='address'?fnow()+86400000:null;if(p.kind==='source'&&p.subject==='SRC-DEMO-PM'){finance.sourceVersion++;finance.sourceActive=p.extra.intent!=='archive';finance.payouts.filter(q=>q.source==='SRC-DEMO-PM'&&['prepared','waiting','approved'].includes(q.status)).forEach(q=>{q.approvals=[];q.status='prepared';});}p.history.push({kind:p.kind,subject:p.subject,reason:p.reason,version:p.version,value:p.value,who:p.approvals.map(a=>a.id),status:p.status,effective:p.kind==='address'?new Date(p.activeAt).toISOString():p.kind==='source'?new Date(fnow()).toISOString():new Date(financeUTC(p.effective)).toISOString(),extra:structuredClone(p.extra),tiers:structuredClone(p.tiers||[])});}else p.status='waiting';flog('Подтверждена учебная версия: '+p.kind,'Approved synthetic version: '+p.kind);return true;}
function financeTitle(){if(finance.view==='deposit')return pl('Пополнить кошелёк Shadow','Add funds to Shadow wallet');return state.route==='financeSource'?pl('Собственный источник','Own funding source'):state.route==='partner'?fpartner().name:state.route==='payout'?fpayout()?.id||pl('Выплата','Payout'):state.route==='financePolicy'?financeText(financePolicyKinds[finance.policyKind]):financeText(financeLabels[finance.view]);}
function financeBanner(){return `<p class="support-notice">${fpaid()?pl('Пример будущей платной версии · не активен. Учебные USDT и маршруты не подтверждают возможности площадок.','Future paid-version example · inactive. Synthetic USDT routes do not establish venue capabilities.'):pl('Paper Alpha · комиссия Shadow 0%. Реальные выплаты выключены. Финансирование сервиса не является доходом.','Paper Alpha · Shadow fee 0%. Real payouts are disabled. Service funding is not revenue.')}</p>`;}
function financeFilters(){const hasDates=['overview','movements'].includes(finance.view),hasQuery=finance.view!=='overview';return `<form id="finance-filter-form" class="finance-filters">${hasQuery?`<div class="field"><label for="finance-query">${pl('Поиск по имени или ID','Search by name or ID')}</label><input id="finance-query" value="${escape(finance.filterDraft?.query??finance.query)}"></div>`:''}${supportSelect('finance-venue',t('venue'),[['all',t('all')],['Polymarket','Polymarket'],['Limitless','Limitless']],finance.filterDraft?.venue??finance.venue)}${hasDates?`<details class="finance-period"><summary>${pl('Период · UTC','Period · UTC')}: ${finance.from} — ${finance.to}</summary><div class="finance-date-fields"><div class="field"><label for="finance-from">${pl('С даты','From date')}</label><input id="finance-from" type="date" value="${finance.filterDraft?.from??finance.from}"></div><div class="field"><label for="finance-to">${pl('По дату','To date')}</label><input id="finance-to" type="date" value="${finance.filterDraft?.to??finance.to}"></div></div></details>`:''}<div class="actions"><button class="btn" type="submit">${pl('Применить','Apply')}</button>${fbtn('Сбросить','Reset','reset')}</div></form>`;}
function financeTable(head,rows){return `<div class="table-wrap" tabindex="0" role="region" aria-label="${pl('Таблица: прокрутка по горизонтали','Table: scroll horizontally')}"><table><thead><tr>${head.map(v=>`<th scope="col">${v}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>${!rows.length?`<div class="empty"><h2>${pl('Нет результатов','No results')}</h2>${fbtn('Сбросить фильтры','Reset filters','reset')}</div>`:''}</div>`;}
function fstatus(p){return financeText(({prepared:['Подготовлена','Prepared'],waiting:['Нужен второй владелец','Second owner required'],approved:['Готова к учебной отправке','Ready for synthetic submission'],unknown:['Результат неизвестен','Outcome unknown'],confirmed:['Подтверждена','Confirmed'],failed:['Окончательный отказ подтверждён','Final failure confirmed']})[p.status]);}
function financeOverview(){const entries=financeSelectedEntries(),receipts=entries.filter(x=>x[5]==='receipt').reduce((v,x)=>v+x[4],0);const partners=financePartners.filter(financePartnerIncluded);const debt=fpaid()?partners.reduce((n,p)=>n+(finance.payouts.some(x=>x.partner===p.id&&x.status==='confirmed')?0:p.debt),0):0;const paid=finance.payouts.filter(p=>p.status==='confirmed'&&(finance.venue==='all'||p.venue===finance.venue)).reduce((n,p)=>n+p.amount,0);return `<div class="kpis">${[[['Поступило от дохода','Revenue receipts'],receipts,'movements'],[['Расходы за период','Period expenses'],-entries.filter(x=>x[5]==='expense').reduce((n,x)=>n+x[4],0),'movements'],[['Осталось выплатить','Outstanding liability'],debt,'partners'],[['Учебные выплаты в сеансе','Synthetic payouts this session'],paid,'payouts']].map(([label,v,view])=>`<button class="kpi" data-finance="view" data-view="${view}"><span class="kpi-label">${financeText(label)}</span><strong class="kpi-value">${fmoney(v)}</strong><span class="kpi-note">${pl('Открыть детали','Open details')}</span></button>`).join('')}</div><section class="panel"><div class="table-top"><div><h2>${pl('Поступления и расходы','Receipts and expenses')}</h2><p class="muted">${pl('Собственные средства сервиса · USDT · UTC','Own service funds · USDT · UTC')}</p></div><div class="actions"><label><input type="checkbox" id="finance-receipts" ${finance.showReceipts?'checked':''}> ${pl('Поступления','Receipts')}</label><label><input type="checkbox" id="finance-expenses" ${finance.showExpenses?'checked':''}> ${pl('Расходы','Expenses')}</label></div></div><div class="finance-chart">${financeDates.filter(d=>d>=finance.from&&d<=finance.to).map(d=>{const a=entries.filter(x=>x[1]===d&&x[4]>0).reduce((n,x)=>n+x[4],0),b=-entries.filter(x=>x[1]===d&&x[4]<0).reduce((n,x)=>n+x[4],0);return `<button data-finance="day" data-day="${d}" aria-label="${d}: ${pl('поступило','receipts')} ${a}, ${pl('расходы','expenses')} ${b} USDT"><span>${d.slice(8)} ${pl('окт.','Oct')}</span><span class="finance-bars">${finance.showReceipts?`<i style="--bar:${a/2}%" class="receipt"></i>`:''}${finance.showExpenses?`<i style="--bar:${b/2}%" class="expense"></i>`:''}</span><strong>${finance.showReceipts?a:'—'} / ${finance.showExpenses?b:'—'}</strong></button>`;}).join('')||`<p>${pl('В выбранном периоде нет учебных событий.','No synthetic events in this period.')}</p>`}</div><p class="muted">${pl('Шкала: 0–200 USDT. Нажмите дату для записей дня. Поступления включают финансирование; оно не является доходом.','Scale: 0–200 USDT. Select a date for records. Receipts include funding; funding is not revenue.')}</p></section><div class="split"><section class="panel"><h2>${pl('Доступно источнику выплат','Payout source availability')}</h2><p>SRC-DEMO-PM · ${pl('снимок 23 октября + операции сеанса','23 Oct snapshot + session operations')}</p><p>${pl('Пригодно','Eligible')}: ${fmoney(finance.eligible+financeFunded()-fsettled('SRC-DEMO-PM'))} · ${pl('Свободно до комиссии','Free before fees')}: ${fmoney(ffree('SRC-DEMO-PM'))}</p>${fbtn('Состав остатка','Balance breakdown','source')}</section><section class="panel"><h2>${pl('Начисления отдельно от поступлений','Accruals are separate from receipts')}</h2><p>${pl('Начислено по снимку','Accrued in snapshot')}: ${fmoney(fpaid()?240:0)}. ${pl('Не сопоставлено с поступлениями','Not matched to receipts')}: ${fmoney(fpaid()?60:0)}.</p><p class="muted">${pl('Снимок всех площадок на 23 октября; суммы не меняются от периода графика.','All-venue snapshot on 23 October; amounts do not change with the chart period.')}</p>${fbtn('Партнёры и доступный долг','Partners and available liability','view','data-view="partners"')}</section></div>`;}
function financeMovements(){const rows=financeSelectedEntries();return (typeof depositAllowed==='function'&&depositAllowed()&&finance.deposit?.records.length?depositHistory():'')+`<p class="support-notice">${pl('Исторический учебный снимок за 17–23 октября. Операции текущего сеанса показаны отдельно в выплатах и собственных источниках.','Historical synthetic snapshot for 17–23 October. Current-session operations are shown separately under payouts and own sources.')}</p>`+financeTable([pl('Запись','Record'),pl('Дата · UTC','Date · UTC'),t('venue'),pl('Назначение','Purpose'),pl('Изменение средств','Movement')],rows.map(x=>`<tr><td>${fbtn(x[0],x[0],'movement',`data-id="${x[0]}"`)}</td><td>${x[1]}</td><td>${x[2]}</td><td>${financeText(x[3])}</td><td>${fmoney(x[4])}</td></tr>`))+`<p class="muted">${pl('Каждое событие учитывается один раз. Исправление — отдельная запись; перенос между своими источниками не создаёт доход.','Each event is recorded once. Corrections are separate entries; own-source transfers do not create revenue.')}</p>`;}
function financePartnersPage(){const rows=financePartners.filter(p=>(finance.venue==='all'||p.venue===finance.venue)&&[p.name,p.id].join(' ').toLowerCase().includes(finance.query.toLowerCase()));return financeTable([pl('Партнёр','Partner'),t('venue'),pl('Доступный долг','Available liability'),pl('Не подтверждено','Unconfirmed'),pl('Статус выплаты','Payout status')],rows.map(p=>{const pay=finance.payouts.find(x=>x.partner===p.id&&x.status!=='failed');return `<tr><td>${fbtn(p.name,p.name,'partner',`data-id="${p.id}"`)}<small>${p.id}</small></td><td>${p.venue}</td><td>${fmoney(fpaid()&&!pay?p.debt:0)}</td><td>${fmoney(fpaid()?p.pending:0)}</td><td>${pay?fstatus(pay):pl('Нет операции','No operation')}</td></tr>`;}));}
function financePartner(){const p=fpartner(),pay=finance.payouts.find(x=>x.partner===p.id&&x.status!=='failed');return heading(p.name,p.id+' · '+p.venue,fbtn('К партнёрам','Back to partners','view','data-view="partners"'))+financeBanner()+`<div class="split"><section class="panel"><h2>${pl('Доступный непогашенный долг','Available unpaid liability')}</h2><strong class="kpi-value">${fmoney(fpaid()&&!pay?p.debt:0)}</strong><p>${pl('Одна выплата — весь доступный долг по этой площадке. Неподтверждённое и уже зарезервированное исключены.','One payout covers the entire available liability for this venue. Unconfirmed and already reserved amounts are excluded.')}</p>${pay?fbtn('Открыть выплату','Open payout','payout',`data-id="${pay.id}"`):fbtn('Проверить полную выплату','Check full payout','prepare',!fpaid()?'disabled':'',true)}</section><section class="panel"><h2>${pl('Получатель','Recipient')}</h2><p class="full-address">${financeRecipient(p).address}</p><p>${escape(financeRecipient(p).network)} · ${escape(financeRecipient(p).asset)} · v${financeRecipient(p).version}</p>${fbtn('Изменение реквизитов','Change recipient details','policy','data-kind="address"')}</section></div><section class="panel"><h2>${pl('Условия партнёра','Partner terms')}</h2><p>PARTNER-DEMO-v1 · ${pl('Подтверждены двумя владельцами · пример будущей версии','Approved by two owners · future-version example')}</p>${fbtn('Денежное правило','Monetary rule','policy','data-kind="partner"')}</section>`;}
function financePayout(){const p=fpayout();if(!p)return heading(pl('Выплата не найдена','Payout not found'));const approvals=fapprovals(p);return heading(p.id,financePartners.find(x=>x.id===p.partner).name+' · '+p.venue,fbtn('К выплатам','Back to payouts','view','data-view="payouts"'))+financeBanner()+`<div class="support-notice"><strong>${fstatus(p)}</strong><p>${p.status==='unknown'?pl('Резерв сохранён. Повтор запрещён до сверки; проверка не отправляет деньги.','Reserve retained. Resubmission is blocked until reconciliation; checking does not send funds.'):pl('Проверьте всю сумму, получателя, маршрут и комиссию.','Check the entire amount, recipient, route and fee.')}</p></div><div class="split"><section class="panel"><h2>${pl('Сумма и резерв','Amount and reserve')}</h2>${[[pl('Весь доступный долг','Entire available liability'),fmoney(p.amount)],[pl('Комиссия за счёт сервиса','Fee paid by service'),fmoney(p.fee)],[pl('Резерв этой операции','This operation reserve'),fmoney(['confirmed','failed'].includes(p.status)?0:p.amount+p.fee)],[pl('Подтверждённый долг сейчас','Confirmed liability now'),fmoney(p.status==='confirmed'?0:p.amount)]].map(([a,b])=>`<div class="money-row"><span>${a}</span><strong>${b}</strong></div>`).join('')}<p>${pl('Повторное открытие использует тот же резерв.','Reopening uses the same reserve.')}</p></section><section class="panel"><h2>${pl('Маршрут','Route')}</h2><p>${p.source} · v${p.sourceVersion} · ${escape(p.asset)} · ${escape(p.network)}</p><p class="full-address">${p.address}</p><p>${p.ruleVersion} · ${p.guardVersion}</p><p>${pl('Долг и плательщик комиссии зафиксированы при начислении. Новые партнёрские правила не меняют этот долг. Действующие защитные ограничения проверяются перед отправкой.','Liability and fee payer were fixed at accrual. New partner rules do not change this debt. Current safeguards are rechecked before submission.')}</p><p>${pl('Внешнее подтверждение','External confirmation')}: ${p.external||pl('Ещё нет','None yet')}</p></section></div><section class="panel"><h2>${pl('Подтверждения владельцев','Owner approvals')}</h2><p>${approvals.length} / ${p.required} · ${pl('Учебный срок: 10 минут; срок реального правила задаётся отдельно.','Example expiry: 10 minutes; real policy expiry is configured separately.')}</p>${approvals.map(a=>`<p>${a.id} · ${new Date(a.expires).toISOString()}</p>`).join('')}<div class="actions">${['prepared','waiting','approved'].includes(p.status)?fbtn('Проверить личность · демо','Verify identity · demo','proof','',true)+fbtn('Обновить проверку маршрута','Refresh route review','refresh-payout')+fbtn('Подтвердить эту версию','Approve this version','approve')+fbtn('Другой владелец: выйти и войти','Another owner: sign out and in','handoff'):''}${p.status==='approved'?fbtn('Выполнить учебную отправку','Run synthetic submission','submit','',true):''}${p.status==='unknown'?fbtn('Сверить исходную выплату','Reconcile original payout','reconcile','',true):''}${incidents.records.some(i=>i.financePayout===p.id)?fbtn('Связанный инцидент','Linked incident','finance-incident'):''}</div></section>`;}
function financeSource(){return `<section class="panel"><h2>${pl('Состав остатка SRC-DEMO-PM','SRC-DEMO-PM balance breakdown')}</h2>${[[pl('Фактический снимок','Observed snapshot'),finance.eligible+financeFunded()-fsettled('SRC-DEMO-PM')+(fpaid()?20:0)],[pl('Неподтверждённое — уже исключено','Unconfirmed — already excluded'),fpaid()?20:0],[pl('Подтверждено и пригодно','Confirmed eligible balance'),finance.eligible+financeFunded()-fsettled('SRC-DEMO-PM')],[pl('Другие уникальные резервы','Other unique reserves'),finance.otherReserves],[pl('Операционный резерв','Operational reserve'),finance.operational],[pl('Резервы созданных выплат','Prepared payout reserves'),freserved('SRC-DEMO-PM')],[pl('Свободно до новой комиссии','Free before new fee'),ffree('SRC-DEMO-PM')]].map(([a,v])=>`<div class="money-row"><span>${a}</span><strong>${fmoney(v)}</strong></div>`).join('')}<p>${pl('Показатели вложены, складывать все строки нельзя. Несопоставленные и заблокированные суммы не вычитаются второй раз. Основа — учебный снимок 23.10.2026 12:00 UTC плюс подтверждённые операции этого сеанса.','Categories overlap; do not add all rows. Unmatched and blocked amounts are not deducted twice. Based on the 23 Oct 2026 12:00 UTC synthetic snapshot plus confirmed operations in this session.')}</p><p class="full-address">${escape(financeSourceConfig()?.sourceAddress||'0x3333333333333333333333333333333333333333')}</p><p>${escape(financeSourceConfig()?.network||'Demo network')} · ${escape(financeSourceConfig()?.asset||'USDT / DEMO-CONTRACT')}</p><p>${pl('Изменённая сеть, актив или назначение требуют отдельного зарегистрированного маршрута. Текущий учебный перевод тогда блокируется.','A changed network, asset or purpose requires a separately registered route. The current synthetic transfer is then blocked.')}</p><p>${pl('Состояние','State')}: ${finance.sourceActive?pl('Учебный источник активен','Synthetic source active'):pl('Отключён','Disabled')}</p><div class="actions">${fbtn('Изменить конфигурацию','Edit configuration','policy','data-kind="source" data-source="SRC-DEMO-PM"')}${fbtn('Экстренно отключить','Emergency disable','disable-source',!finance.sourceActive?'disabled':'')}</div></section>`;}
const financeFieldLabels={
 intentVIP:['Действие с VIP','VIP action'],duration:['Срок VIP','VIP duration'],rate:['Комиссия сервиса, %','Service fee, %'],vipRate:['Индивидуальная комиссия, %','Individual fee, %'],share:['Доля партнёра, %','Partner share, %'],threshold:['Порог второго владельца, USDT','Second-owner threshold, USDT'],name:['Название источника','Source name'],address:['Полный адрес','Full address'],basis:['Версия базы расчёта','Calculation basis version'],rounding:['Версия округления','Rounding version'],end:['Окончание · UTC','Ends · UTC'],attribution:['Окно привлечения, дней','Attribution window, days'],hold:['Ожидание подтверждения, дней','Confirmation hold, days'],cadence:['Период выплат, дней','Payout interval, days'],minimum:['Минимум выплаты, USDT','Minimum payout, USDT'],daily:['Суточный порог, USDT','Daily threshold, USDT'],perPartner:['Порог партнёру, USDT','Partner threshold, USDT'],perSource:['Порог источнику, USDT','Source threshold, USDT'],newAddress:['Порог новому адресу, USDT','New-address threshold, USDT'],hardMax:['Жёсткий максимум, USDT','Hard maximum, USDT'],timezone:['Граница суток','Day boundary'],feePayer:['Комиссию перевода платит','Transfer fee paid by'],network:['Сеть','Network'],asset:['Актив / контракт','Asset / contract'],sourceAddress:['Адрес собственного источника','Own source address'],controller:['Контролирующее лицо','Controlling party'],signer:['Способ подписания без секретов','Signing method without secrets'],target:['Целевой остаток, USDT','Target balance, USDT'],purpose:['Назначение','Purpose'],direction:['Разрешённое направление','Allowed direction'],intent:['Изменение источника','Source change']};
const financeFields={tariff:['basis','rounding'],vip:['basis','rounding','intentVIP','duration','end'],partner:['basis','rounding','attribution','hold','cadence','minimum','feePayer'],protection:['daily','perPartner','perSource','newAddress','hardMax','timezone','feePayer'],source:['sourceAddress','network','asset','controller','signer','target','hardMax','purpose','direction','intent'],address:['network','asset']};
const financeChoices={intentVIP:[['assign',['Назначить или изменить','Assign or change']],['remove',['Снять VIP','Remove VIP']]],duration:[['until',['До указанной даты','Until a date']],['indefinite',['Бессрочно','Indefinite']]],feePayer:[['service',['Сервис','Service']],['partner',['Партнёр','Partner']]],timezone:[['UTC',['00:00 UTC','00:00 UTC']]],purpose:[['payout',['Выплаты','Payouts']],['income',['Доход','Revenue']],['funding',['Финансирование','Funding']]],direction:[['partner',['Зарегистрированные партнёры этой площадки','Registered partners on this venue']]],intent:[['edit',['Изменить','Edit']],['reactivate',['Повторно активировать','Reactivate']],['archive',['Архивировать','Archive']]]};
const financeNumericFields=['attribution','hold','cadence','minimum','daily','perPartner','perSource','newAddress','hardMax','target'];
function financeTiers(p){p.tiers??=[];return `<h3>${pl('Накопительные реферальные уровни','Cumulative referral tiers')}</h3><p>${pl('Порог — накопленное число подтверждённых клиентов. Доля — процент от утверждённой базы дохода.','Threshold is the accumulated count of confirmed clients. Share is a percentage of the approved revenue basis.')}</p>${financeTable([pl('От клиентов','From clients'),pl('Доля, %','Share, %'),pl('Действие','Action')],p.tiers.map((x,i)=>`<tr><td><input type="number" min="0" step="1" value="${x.threshold}" data-finance-tier="threshold" data-index="${i}" aria-label="${pl('Порог уровня','Tier threshold')} ${i+1}" ${['published','cooldown','active'].includes(p.status)?'readonly':''}></td><td><input type="number" min="0" max="100" step="0.01" value="${x.share}" data-finance-tier="share" data-index="${i}" aria-label="${pl('Доля уровня','Tier share')} ${i+1}" ${['published','cooldown','active'].includes(p.status)?'readonly':''}></td><td>${fbtn('Удалить уровень','Remove tier','tier-remove',`data-index="${i}" ${['published','cooldown','active'].includes(p.status)?'disabled':''}`)}</td></tr>`))}${fbtn('Добавить уровень','Add tier','tier-add',['published','cooldown','active'].includes(p.status)?'disabled':'')}`;}
function financeTiersValid(p){return p.kind!=='partner'||Array.isArray(p.tiers)&&p.tiers.length>0&&p.tiers.every((x,i)=>String(x.threshold).trim()!==''&&String(x.share).trim()!==''&&Number.isInteger(Number(x.threshold))&&Number(x.threshold)>=0&&Number.isFinite(Number(x.share))&&Number(x.share)>=0&&Number(x.share)<=100&&(i===0||Number(x.threshold)>Number(p.tiers[i-1].threshold)));}

function financeExtraFields(p){p.extra??={};return `<div class="support-filters">${financeFields[p.kind].map(key=>{const val=p.extra[key]??'',locked=['published','cooldown','active'].includes(p.status),label=financeText(financeFieldLabels[key]);return `<div class="field"><label for="finance-extra-${key}">${label}</label>${financeChoices[key]?`<select id="finance-extra-${key}" data-finance-extra="${key}" ${locked?'disabled':''}>${options([['',pl('Выберите','Choose')],...financeChoices[key].map(([v,l])=>[v,financeText(l)])],val)}</select>`:`<input id="finance-extra-${key}" data-finance-extra="${key}" type="${financeNumericFields.includes(key)?'number':key==='end'?'datetime-local':'text'}" ${financeNumericFields.includes(key)?'min="0" step="0.01"':''} value="${escape(val)}" ${locked?'readonly':''}>`}</div>`;}).join('')}</div><p class="muted">${p.kind==='vip'?pl('Получатель — конкретный пользователь выше. VIP партнёра не изменяется. Выберите окончание или бессрочное назначение. При снятии и окончании возвращается обычный применимый тариф.','The recipient is the specific user above. Partner VIP is unchanged. Choose an end date or indefinite assignment. Removal and expiry restore the regular applicable tariff.'):p.kind==='partner'?pl('Новые значения применяются к новым начислениям. Подтверждённый долг не пересчитывается. Реферальная лестница накопительная.','New values apply to new accruals. Confirmed liabilities are not recalculated. Referral tiers are cumulative.'):p.kind==='protection'?pl('Защитные пороги требуют второго владельца. Жёсткий максимум запрещает отправку и не обходится вторым согласием.','Safeguard thresholds require another owner. The hard maximum blocks submission and cannot be bypassed by second approval.'):pl('Пустое значение не считается нулём. Реальные параметры требуют отдельного решения.','An empty value is not zero. Real parameters require a separate decision.')}</p>`;}
function financeExtraValid(p){p.extra??={};if(!financeFields[p.kind].every(k=>k==='end'&&p.extra.duration==='indefinite'||String(p.extra[k]??'').trim()!==''))return false;for(const k of financeFields[p.kind]){const v=p.extra[k];if(financeNumericFields.includes(k)&&(!Number.isFinite(Number(v))||Number(v)<0))return false;if(financeChoices[k]&&!financeChoices[k].some(x=>x[0]===v))return false;}if(p.kind==='vip'&&p.extra.duration!=='indefinite'&&(!Number.isFinite(financeUTC(p.extra.end))||financeUTC(p.extra.end)<=financeUTC(p.effective)))return false;if(p.kind==='source'&&(!/^0x[a-fA-F0-9]{40}$/.test(p.extra.sourceAddress)||Number(p.extra.target)>Number(p.extra.hardMax)))return false;if(p.kind==='protection'&&Number(p.value)>Number(p.extra.hardMax))return false;return true;}
function financePolicyExample(p){p.value=p.kind==='address'?'0x4444444444444444444444444444444444444444':p.kind==='source'?'Demo payout source':p.kind==='protection'?'150':'1';p.reason=pl('Учебный пример для проверки версии','Synthetic example for version review');p.extra={basis:'BASIS-DEMO-v1',rounding:'ROUND-DEMO-v1',end:'2026-12-01T00:00',intentVIP:'assign',duration:'until',attribution:'30',hold:'7',cadence:'7',minimum:'10',feePayer:'service',daily:'500',perPartner:'200',perSource:'500',newAddress:'100',hardMax:'1000',timezone:'UTC',sourceAddress:'0x3333333333333333333333333333333333333333',network:'Demo network',asset:'USDT / DEMO-CONTRACT',controller:'Shadow · DEMO',signer:'DEMO signer · no key',target:'200',purpose:'payout',direction:'partner',intent:'edit'};p.tiers=[{threshold:0,share:1},{threshold:10,share:2}];p.checked=false;p.approvals=[];finance.proof=null;}
function financeDisplayValue(key,value){const choice=financeChoices[key]?.find(x=>x[0]===value);return choice?financeText(choice[1]):value??'—';}
function financePolicyComparison(p){const old=p.history.filter(h=>h.version<p.version).at(-1)||(p.kind==='address'?{value:financePartners.find(x=>x.id===p.subject)?.address,extra:{network:'Demo network',asset:'USDT / DEMO-CONTRACT'}}:null),shown={...p,effective:p.kind==='address'?(p.activeAt?new Date(p.activeAt).toISOString():pl('Через 24 часа после второго согласия','24 hours after second approval')):p.kind==='source'?pl('После второго согласия','After second approval'):p.effective};return financeTable([pl('Параметр','Parameter'),pl('Предыдущая версия','Previous version'),pl('Предлагается','Proposed')],[['value',pl('Основное значение','Main value')],['effective',pl('Начало · UTC','Effective from · UTC')],['reason',pl('Причина','Reason')],...financeFields[p.kind].map(k=>[k,financeText(financeFieldLabels[k])])].map(([key,label])=>`<tr><td>${label}</td><td>${escape(financeDisplayValue(key,['value','effective','reason'].includes(key)?old?.[key]:old?.extra?.[key]))}</td><td>${escape(financeDisplayValue(key,['value','effective','reason'].includes(key)?shown[key]:p.extra?.[key]))}</td></tr>`));}

function financePolicy(){const p=fpolicy(),dual=fpolicyDual(p.kind);const hint=p.kind==='address'?['Полный новый адрес. Второй владелец запускает 24 часа ожидания; время само по себе не отменяет запреты.','Full new address. The second owner starts a 24-hour delay; time alone does not remove restrictions.']:p.kind==='source'?['Имя зарегистрированного источника. Направление, сеть и актив сохраняются в учебном маршруте; ключи не вводятся.','Registered source name. Direction, network and asset stay within the synthetic route; no keys are entered.']:['Учебное значение, не действующее правило сервиса. Проверка диапазона 0–100 относится только к этому примеру.','Synthetic value, not active service policy. The 0–100 validation range is for this example only.'];return heading(financeText(financePolicyKinds[p.kind]),pl('Проверка → подтверждение → новая версия. История не пересчитывается.','Review → approval → new version. Historical entries are not recalculated.'),finance.policyReturn==='user'?fbtn('К пользователю','Back to user','policy-back'):finance.policyReturn==='financeSource'?fbtn('К источникам','Back to sources','policy-back'):fbtn('К настройкам','Back to settings','view','data-view="settings"'))+financeBanner()+`<section class="panel"><h2>${pl('Версия','Version')} ${p.version} · ${pl(...({draft:['Черновик','Draft'],waiting:['Нужен второй владелец','Second owner required'],published:['Учебная версия сохранена','Synthetic version saved'],active:['Активная учебная версия','Active synthetic version'],cooldown:['Ожидание 24 часа','24-hour wait'],cancelled:['Изменение отменено','Change cancelled']})[p.status])}</h2><p>${escape(p.subject)} · ${p.venue==='all'?pl('Все площадки','All venues'):escape(p.venue)} · ${pl('Точная область этой версии','Exact scope of this version')}</p><p>${pl(...hint)}</p><p>${dual?pl('Нужны два разных владельца.','Two different owners are required.'):pl('Публикует один владелец. Второе согласование не требуется.','One owner publishes. A second approval is not required.')}</p><form id="finance-policy-form"><div class="support-filters"><div class="field"><label for="finance-value">${p.kind==='address'?pl('Адрес целиком','Full address'):p.kind==='source'?pl('Название источника','Source name'):financeText(financeFieldLabels[p.kind==='tariff'?'rate':p.kind==='vip'?'vipRate':p.kind==='partner'?'share':'threshold'])}</label><input id="finance-value" value="${escape(p.value)}" ${['published','cooldown','active'].includes(p.status)?'readonly':''}></div>${!['address','source'].includes(p.kind)?`<div class="field"><label for="finance-effective">${pl('Действует с · UTC','Effective from · UTC')}</label><input type="datetime-local" id="finance-effective" value="${p.effective}" ${['published','cooldown','active'].includes(p.status)?'readonly':''}></div>`:''}<div class="field"><label for="finance-reason">${pl('Причина изменения','Reason for change')}</label><input id="finance-reason" value="${escape(p.reason)}" ${['published','cooldown','active'].includes(p.status)?'readonly':''}></div></div>${financeExtraFields(p)}${p.kind==='partner'?financeTiers(p):''}<div class="actions"><button class="btn" type="submit" ${['published','cooldown','active'].includes(p.status)?'disabled':''}>${pl('Проверить изменение','Review change')}</button>${fbtn('Проверить личность · демо','Verify identity · demo','policy-proof',!p.checked||!['draft','waiting'].includes(p.status)?'disabled':'')}${fbtn('Подтвердить версию','Approve version','policy-approve',!p.checked||!['draft','waiting'].includes(p.status)?'disabled':'',true)}${dual&&['draft','waiting'].includes(p.status)?fbtn('Другой владелец: выйти и войти','Another owner: sign out and in','handoff'):''}</div></form><details class="account-test"><summary>${pl('Заполненный учебный пример','Prepared synthetic example')}</summary>${fbtn('Заполнить вымышленными значениями','Fill synthetic values','policy-example',['published','cooldown','active'].includes(p.status)?'disabled':'')}</details>${p.checked?financePolicyComparison(p)+financePolicyImpact(p)+`<p class="support-notice">${pl('Проверено: новая версия меняет только будущие учебные значения. Paper Alpha остаётся 0%.','Reviewed: the new version only changes future synthetic values. Paper Alpha stays at 0%.')}</p>`:''}${p.status==='active'?`<p class="support-notice">${pl('Точная версия реквизитов активирована','Exact recipient version activated')}: ${escape(p.activeVersion?.effective||'—')}</p>`:''}${p.status==='cooldown'&&p.activeAt?`<p>${pl('Второе подтверждение','Second approval')}: ${new Date(p.activeAt-86400000).toISOString()}<br>${pl('Плановая активация','Scheduled activation')}: ${new Date(p.activeAt).toISOString()}<br>${pl('Осталось ожидать','Time remaining')}: ${Math.max(0,Math.ceil((p.activeAt-fnow())/60000))} ${pl('мин.','min')}</p><p>${pl('До этого времени новый адрес недоступен. Отмена не активирует старую заблокированную версию.','The new address is unavailable until then. Cancelling does not reactivate an old blocked version.')}</p>${fbtn('Повторно проверить и активировать','Recheck and activate','address-activate',fnow()<p.activeAt?'disabled':'')}${fbtn('Отменить изменение','Cancel change','policy-cancel')}<details class="account-test"><summary>${pl('Учебные часы','Synthetic clock')}</summary><p>${new Date(fnow()).toISOString()}</p>${fbtn('Пропустить 24 часа только в примере','Advance 24 hours in this example','clock-advance')}</details>`:''}<p>${pl('Подтвердили','Approved by')}: ${p.approvals.map(a=>a.id+' · '+new Date(a.issuedAt||fnow()).toISOString()).join(', ')||'—'}</p><div class="actions">${fbtn('Создать следующую версию','Create next version','policy-new',p.status==='cooldown'?'disabled':'')}</div></section><section class="panel"><h2>${pl('История версий','Version history')}</h2>${p.history.length?p.history.map(h=>`<p>v${h.version} · ${escape(h.value)} · ${h.who.join(', ')} · ${h.effective} UTC ${fbtn('Взять за основу','Use as draft','policy-restore',`data-version="${h.version}"`)}</p>`).join(''):`<p>${pl('Опубликованных учебных версий пока нет','No published synthetic versions yet')}</p>`}</section>`;}
function financeContent(){if(!financeAccess().read)return heading(pl('Финансы недоступны этому назначению','Finance is unavailable for this assignment'),pl('Просмотр клиентских демо-сумм не даёт доступа к деньгам сервиса.','Viewing client demo amounts does not grant service-finance access.'));const notice=finance.notice?`<p class="support-notice" role="status">${financeText(finance.notice)}</p>`:'';const error=finance.error?`<p class="account-error" role="alert">${financeText(finance.error)}</p>`:'';if(state.route==='financeSource')return heading(pl('Собственный источник','Own funding source'),'SRC-DEMO-PM',fbtn('Назад к обзору','Back to overview','view','data-view="overview"'))+financeBanner()+notice+error+fbtn('Вывести собственные средства','Withdraw own funds','view','data-view="own"',true)+financeSource()+financeTreasury();if(state.route==='partner')return notice+error+financePartner();if(state.route==='payout')return notice+error+financePayout();if(state.route==='financePolicy')return notice+error+financePolicy();return heading(financeTitle(),pl('Деньги сервиса отдельно от клиентских и демо-средств','Service funds separate from user and demo funds'))+`<div class="tabs">${Object.entries(financeLabels).map(([key,l])=>fbtn(...l,'view',`data-view="${key}" aria-current="${finance.view===key?'page':'false'}"`)).join('')}${reconciliationAccess().read?button(t('reconciliation'),'reconciliation'):''}</div>`+financeBanner()+notice+error+(typeof depositAllowed==='function'&&depositAllowed()&&finance.view!=='deposit'&&finance.view!=='own'?`<div class="actions"><button type="button" class="btn primary" data-deposit="open">${pl('Пополнить кошелёк Shadow','Add funds to Shadow wallet')}</button></div>`:'')+(['settings','own','deposit'].includes(finance.view)?'':financeFilters())+({deposit:()=>typeof depositPage==='function'?depositPage():'',own:ownWithdrawalPage,overview:financeOverview,movements:financeMovements,partners:financePartnersPage,payouts:()=>financeTable([pl('Выплата','Payout'),t('venue'),pl('Вся сумма','Full amount'),pl('Результат','Outcome')],finance.payouts.filter(p=>(finance.venue==='all'||finance.venue===p.venue)&&p.id.toLowerCase().includes(finance.query.toLowerCase())).map(p=>`<tr><td>${fbtn(p.id,p.id,'payout',`data-id="${p.id}"`)}</td><td>${p.venue}</td><td>${fmoney(p.amount)}</td><td>${fstatus(p)}</td></tr>`)),settings:()=>`<div class="finance-settings">${Object.entries(financePolicyKinds).map(([k,v])=>`<section class="panel"><h2>${financeText(v)}</h2><p>${fpolicyDual(k)?pl('Изменение подтверждают два владельца','Changes require two owners'):pl('Публикует один владелец','One owner publishes')}</p>${fbtn(k==='vip'?'Выбрать пользователя':'Открыть',k==='vip'?'Choose user':'Open','policy',`data-kind="${k}" aria-label="${pl('Открыть: ','Open: ')+financeText(v)}"`)}</section>`).join('')}</div>`})[finance.view]()+(['own','deposit'].includes(finance.view)?'':`<details class="account-test"><summary>${pl('Учебные сценарии — не рабочие настройки','Test scenarios — not operating settings')}</summary><div class="actions">${fbtn('Paper Alpha · 0%','Paper Alpha · 0%','scenario','data-scenario="alpha"')}${fbtn('Будущая платная версия · пример','Future paid-version example','scenario','data-scenario="future"')}</div>${supportSelect('finance-outcome',pl('Следующий исход','Next outcome'),[['success',pl('Подтверждено','Confirmed')],['failure',pl('Окончательный отказ','Final failure')],['unknown',pl('Результат неизвестен','Outcome unknown')]],finance.outcome)}${supportSelect('finance-block',pl('Ограничение','Restriction'),[['none',pl('Нет','None')],['technical',pl('Технический режим','Technical mode')],['hard',pl('Жёсткий запрет','Hard block')]],finance.block)}${supportSelect('finance-threshold',pl('Учебный защитный порог','Example second-approval threshold'),[['150','150 USDT'],['100','100 USDT']],String(finance.threshold))}<p>${pl('Изменение сценария сбрасывает учебные операции. Реальный режим не включается.','Changing the scenario clears synthetic operations. It never activates live mode.')}</p></details>`);}
function financeAction(a,el={dataset:{}}){if(!financeAccess().read)return false;finance.error=null;finance.notice=null;if(a==='incident-payout'){finance.payoutId=el.dataset.id;navigate('payout');return true;}if(a.startsWith('transfer-')){financeTransferAction(a,el.dataset.id);render();return true;}if(a==='open'||a==='view'){finance.view=el?.dataset.view||'overview';navigate('finance');return true;}if(a==='reset'){finance.filterDraft=null;Object.assign(finance,{query:'',venue:'all',from:'2026-10-17',to:'2026-10-23'});}else if(a==='day'){finance.from=finance.to=el.dataset.day;finance.view='movements';navigate('finance');return true;}else if(a==='partner'){finance.partnerId=el.dataset.id;navigate('partner');return true;}else if(a==='payout'){finance.payoutId=el.dataset.id;navigate('payout');return true;}else if(a==='source-create'){finance.sourceTarget='SRC-NEW-'+(Object.keys(finance.policies).filter(k=>k.startsWith('source:SRC-NEW-')).length+1);finance.policyKind='source';finance.policyReturn='financeSource';navigate('financePolicy');return true;}else if(a==='source'){finance.sourceTarget='SRC-DEMO-PM';navigate('financeSource');return true;}else if(a==='policy-back'){navigate(finance.policyReturn==='financeSource'?'financeSource':'user');return true;}else if(a==='policy'){if(el.dataset.kind==='vip'&&state.route!=='user'){navigate('users');return true;}if(el.dataset.kind==='source'&&state.route!=='financeSource'){navigate('financeSource');return true;}finance.policyReturn=state.route;finance.policyKind=el.dataset.kind;if(finance.policyKind==='source')finance.sourceTarget=el.dataset.source||'SRC-DEMO-PM';if(finance.policyKind==='vip')finance.vipUserId=state.userId;navigate('financePolicy');return true;}else if(a==='movement'){finance.notice=[`${el.dataset.id}: подтверждённое учебное событие. Источник: снимок 23.10.2026; исправления создаются отдельными записями.`,`${el.dataset.id}: confirmed synthetic event. Source: snapshot 23 Oct 2026; corrections create separate entries.`];}else if(a==='scenario'){const scenario=el.dataset.scenario;finance=newFinance();finance.scenario=scenario;if(scenario==='future'){finance.eligible=200;finance.otherReserves=50;}}else if(a==='prepare'){if(!financePrepare())render();return true;}else if(a==='refresh-payout'){const p=fpayout(),partner=p&&financePartners.find(x=>x.id===p.partner);if(p&&['prepared','waiting','approved'].includes(p.status)&&!fblocked(p.source)&&!['waiting','cooldown'].includes(finance.policies['address:'+p.partner]?.status)){const r=financeRecipient(partner);p.address=r.address;p.recipientVersion=r.version;p.network=r.network;p.asset=r.asset;p.sourceVersion=p.source==='SRC-DEMO-PM'?finance.sourceVersion:1;p.approvals=[];p.status='prepared';finance.proof=null;finance.notice=['Маршрут обновлён. Повторно проверьте полные реквизиты и подтвердите новую версию.','Route refreshed. Review full recipient details and approve the new version again.'];}else finance.error=['Обновление недоступно: сначала завершите ожидание или сверку.','Refresh unavailable: complete the wait or reconciliation first.'];}else if(a==='proof'){const p=fpayout();if(p&&!fblocked(p.source)){finance.proof={id:actor().id,digest:fdigest(p),expires:Date.now()+300000};finance.notice=['Личность подтверждена в учебном примере.','Identity verified in this synthetic example.'];}}else if(a==='approve'){if(!financeApprove())finance.error=['Нужны актуальная проверка личности и независимый владелец; проверьте ограничения.','A fresh identity check and an independent owner are required; check restrictions.'];}else if(a==='submit'){if(!financeSubmit())finance.error=['Отправка запрещена: проверьте подтверждения, срок, источник и ограничения.','Submission blocked: check approvals, expiry, source and restrictions.'];}else if(a==='finance-incident'){const p=fpayout();if(p){const x=financeEnsureIncident(p);incidents.id=x.id;finance.returnIncident=true;navigate('incident');return true;}}else if(a==='return-payout'){finance.returnIncident=false;navigate('payout');return true;}else if(a==='reconcile'){const p=fpayout();if(p?.status==='unknown'){if(finance.outcome==='success'){p.status='confirmed';p.external='TX-DEMO-'+p.id;p.completedAt=new Date(fnow()).toISOString();flog('Сверка подтвердила исходную выплату','Reconciliation confirmed the original payout');}else if(finance.outcome==='failure'){p.status='failed';flog('Сверка подтвердила окончательный отказ','Reconciliation confirmed final failure');}else finance.notice=['Результат всё ещё неизвестен. Повтор запрещён.','Outcome remains unknown. Resubmission is blocked.'];const i=incidents.records.find(i=>i.financePayout===p.id);if(i&&['confirmed','failed'].includes(p.status)){i.resolved=true;i.evidence=p.external||'FINAL-FAILURE-'+p.id;incidentEvent(i,'Подтверждён исход исходной выплаты','Original payout outcome confirmed');}}}else if(a==='handoff'){finance.handoff=true;finance.incidentRecords=structuredClone(incidents.records.filter(i=>i.financePayout));finance.handoffUser=state.userId;finance.resume=state.route;finance.proof=null;account.logged=false;navigate('entry');return true;}else if(a==='disable-source'){finance.sourceActive=false;finance.sourceVersion++;finance.proof=null;finance.payouts.filter(p=>p.source==='SRC-DEMO-PM').forEach(p=>p.approvals=[]);finance.notice=['Источник экстренно отключён одним владельцем. Повторная активация требует двоих.','Source disabled by one owner. Reactivation requires two owners.'];}else if(a==='tier-add'||a==='tier-remove'){const p=fpolicy();if(!['published','cooldown','active'].includes(p.status)){p.tiers??=[];if(a==='tier-add')p.tiers.push({threshold:'',share:''});else p.tiers.splice(Number(el.dataset.index),1);p.checked=false;p.approvals=[];p.status='draft';finance.proof=null;}}else if(a==='policy-example'){const p=fpolicy();if(!['published','cooldown','active'].includes(p.status))financePolicyExample(p);}else if(a==='policy-proof'){const p=fpolicy();if(p.checked&&fcheckPolicy(p))finance.proof={id:actor().id,digest:fpolicyDigest(p),expires:Date.now()+300000};}else if(a==='policy-approve'){if(!financePolicyApprove())finance.error=['Проверьте изменение и личность. Один сотрудник не подтверждает дважды.','Review the change and verify identity. One employee cannot approve twice.'];}else if(a==='clock-advance'){finance.clockOffset+=86400000;}else if(a==='address-activate'){const p=fpolicy();if(p.kind==='address'&&p.status==='cooldown'&&fnow()>=p.activeAt&&!fblocked()){p.status='active';p.activeVersion=structuredClone({version:p.version,value:p.value,extra:p.extra,effective:new Date(fnow()).toISOString()});flog('Активирована точная версия адреса после 24 часов','Exact recipient version activated after 24 hours');}else finance.error=['Активация запрещена: ожидание или действующее ограничение.','Activation blocked: wait period or active restriction.'];}else if(a==='policy-cancel'){const p=fpolicy();if(p.status==='cooldown'){p.status='cancelled';p.activeAt=null;p.approvals=[];}}else if(a==='policy-new'||a==='policy-restore'){const p=fpolicy();if(p.status==='cooldown'){finance.error=['Сначала отмените ожидающее изменение или дождитесь активации.','Cancel the pending change or complete activation first.'];render();return false;}const h=p.history.find(h=>h.version===Number(el.dataset.version));if(h){p.value=h.value;p.extra=structuredClone(h.extra);p.tiers=structuredClone(h.tiers||[]);}p.version++;p.status='draft';p.approvals=[];p.checked=false;p.activeAt=null;finance.proof=null;}render();return true;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-finance]');if(el&&!el.disabled)financeAction(el.dataset.finance,el);});
document.addEventListener('input',e=>{if(['finance-query','finance-from','finance-to','finance-venue'].includes(e.target.id)){finance.filterDraft??={};finance.filterDraft[e.target.id.replace('finance-','')]=e.target.value;}if(['finance-value','finance-reason','finance-effective'].includes(e.target.id)&&financeAccess().write){const p=fpolicy();if(['published','cooldown','active'].includes(p.status))return;const key=e.target.id.replace('finance-','');p[key]=e.target.value;p.checked=false;p.approvals=[];p.status='draft';finance.proof=null;}});
document.addEventListener('change',e=>{if(!financeAccess().read)return;const id=e.target.id;if(id==='finance-receipts'||id==='finance-expenses'){finance[id==='finance-receipts'?'showReceipts':'showExpenses']=e.target.checked;render();}if(['finance-outcome','finance-block','finance-threshold'].includes(id)){finance[id.replace('finance-','')]=id==='finance-threshold'?Number(e.target.value):e.target.value;if(id!=='finance-outcome'){finance.proof=null;finance.payouts.forEach(p=>{p.approvals=[];if(['prepared','waiting','approved'].includes(p.status)){p.required=p.amount>finance.threshold?2:1;p.status='prepared';}});}render();}});
document.addEventListener('submit',e=>{if(e.target.id==='finance-filter-form'){e.preventDefault();const from=document.querySelector('#finance-from')?.value??finance.from,to=document.querySelector('#finance-to')?.value??finance.to;if(!from||!to||from>to){finance.error=['Начало периода должно быть не позже конца.','Start must be on or before end.'];render();return;}Object.assign(finance,{query:document.querySelector('#finance-query')?.value??'',venue:document.querySelector('#finance-venue').value,from,to,error:null,filterDraft:null});render();}if(e.target.id==='finance-policy-form'){e.preventDefault();const p=fpolicy();p.checked=fcheckPolicy(p);finance.error=p.checked?null:['Заполните корректное значение, дату и причину.','Provide a valid value, date and reason.'];render();}});

document.addEventListener('input',e=>{if(e.target.dataset.financeExtra&&financeAccess().write){const p=fpolicy();if(['published','cooldown','active'].includes(p.status))return;p.extra??={};p.extra[e.target.dataset.financeExtra]=e.target.value;p.checked=false;p.approvals=[];p.status='draft';finance.proof=null;}});

function financePage(){return `<div class="finance-workspace">${financeContent()}</div>`;}

document.addEventListener('input',e=>{if(e.target.dataset.financeTier&&financeAccess().write){const p=fpolicy();if(['published','cooldown','active'].includes(p.status))return;const row=p.tiers?.[Number(e.target.dataset.index)];if(row){row[e.target.dataset.financeTier]=e.target.value;p.checked=false;p.approvals=[];p.status='draft';finance.proof=null;}}});

function financeNav(){if(!financeAccess().read&&!reconciliationAccess().read)return '';return `<details open class="finance-nav"><summary>${icon('money')}${pl('Финансы','Finance')}<span class="chevron">${icon('chevron')}</span></summary>${financeAccess().read?`<button class="sub ${['finance','partner','payout','financePolicy','financeSource'].includes(state.route)?'selected':''}" data-finance="open">${pl('Обзор финансов','Finance overview')}</button>`:''}${reconciliationAccess().read?button(t('reconciliation'),'reconciliation','',`sub ${['reconciliation','reconciliationItem'].includes(state.route)?'selected':''}`):''}</details>`;}

function financeVIPSummary(u){const proposal=finance.policies['vip:'+u.id],p=financeCurrentPolicy('vip:'+u.id);let result=`<p>${t(u.vip?'vipYes':'vipNo')}</p>`;if(p){const expired=p.extra.duration!=='indefinite'&&fnow()>=financeUTC(p.extra.end),active=!expired&&p.extra.intentVIP!=='remove';result=`<p>${pl('Действующая версия условий','Effective terms version')} v${p.version} · ${active?pl('VIP · учебный пример','VIP · synthetic example'):pl('Обычные условия','Regular terms')}</p><p>${pl('Будущая индивидуальная комиссия','Future individual fee')}: ${active?escape(p.value)+'%':pl('обычный применимый тариф','regular applicable tariff')} · ${pl('не включает платный режим','does not enable paid mode')}</p><p>${escape(p.effective)} — ${p.extra.duration==='indefinite'?pl('бессрочно','indefinite'):escape(p.extra.end)+' UTC'}</p>`;}if(proposal){const scheduled=proposal.history.findLast(h=>h.status==='published'&&financeUTC(h.effective)>fnow());if(scheduled)result+=`<p>${pl('Запланирована версия','Scheduled version')} v${scheduled.version} · ${scheduled.effective}</p>`;if(['draft','waiting'].includes(proposal.status))result+=`<p>${pl('Черновик версии','Draft version')} v${proposal.version} · ${pl('действующие условия не меняются','effective terms stay unchanged')}</p>`;}return result;}

function financePolicyImpact(p){let body='';if(['tariff','vip','partner'].includes(p.kind))body=`<p>${pl('Иллюстрация ставки: база 100 USDT ×','Rate illustration: basis 100 USDT ×')} ${escape(p.value)}% = ${fmoney(Number(p.value))}. ${pl('Это пример арифметики, а не новое начисление. Действующий тариф Paper Alpha — 0%.','This illustrates arithmetic, not a new accrual. The effective Paper Alpha fee is 0%.')}</p>`;if(p.kind==='partner')body+=financeTable([pl('От клиентов','From clients'),pl('Предыдущая доля','Previous share'),pl('Предлагаемая доля','Proposed share')],(p.tiers||[]).map(tier=>`<tr><td>${tier.threshold}</td><td>${p.history.filter(h=>h.version<p.version).at(-1)?.tiers?.find(t=>Number(t.threshold)===Number(tier.threshold))?.share??'—'}</td><td>${tier.share}%</td></tr>`))+`<p>${pl('Существующий долг сохраняет PARTNER-DEMO-v1. Эта версия применяется к новым начислениям; прототип не создаёт их автоматически.','Existing liabilities retain PARTNER-DEMO-v1. This version applies to new accruals; the prototype does not generate them automatically.')}</p>`;return `<section class="support-notice"><h3>${pl('Что изменится','What changes')}</h3>${body}<p>${pl('Начало действия','Effective from')}: ${['address','source'].includes(p.kind)?pl('по процедуре выше','according to the procedure above'):escape(p.effective)+' UTC'}</p></section>`;}

// Own-source funding is separate from partner payouts. Only the registered fixture route is available.
function financeTreasury(){finance.transfers??=[];finance.transferDraft??={amount:'50',reason:'',target:'SRC-DEMO-PM'};const d=finance.transferDraft;return `<section class="panel"><h2>${pl('Собственные источники','Own sources')}</h2>${fbtn('Добавить собственный источник','Add own source','source-create')}${financeNewSources()}${financeTable([pl('Источник / назначение','Source / purpose'),t('venue'),pl('Полный адрес','Full address'),pl('Подтверждено','Confirmed')],[['SRC-DEMO-PM',pl('Выплаты партнёрам','Partner payouts'),'Polymarket',financeSourceConfig()?.sourceAddress||'0x3333333333333333333333333333333333333333',finance.eligible+financeFunded()-fsettled('SRC-DEMO-PM')],['SRC-DEMO-LL',pl('Выплаты партнёрам','Partner payouts'),'Limitless','0x6666666666666666666666666666666666666666',120-fsettled('SRC-DEMO-LL')],['SRC-DEMO-FUND',pl('Финансирование владельца','Owner funding'),'Polymarket','0x5555555555555555555555555555555555555555',500-(finance.transfers||[]).filter(x=>x.status==='confirmed').reduce((sum,x)=>sum+x.amount+x.fee,0)]].map(([id,purpose,venue,address,amount])=>`<tr><td>${id}<small>${purpose}</small></td><td>${venue}</td><td class="full-address">${address}</td><td>${fmoney(amount)}</td></tr>`))}<p>${pl('Учебные адреса · USDT / DEMO-CONTRACT. Для источников Polymarket используется одна учебная сеть; маршрут на Limitless не зарегистрирован. Ключи не показываются.','Synthetic addresses · USDT / DEMO-CONTRACT. Polymarket sources use one synthetic network; the Limitless route is not registered. Keys are not displayed.')}</p></section><section class="panel"><h2>${pl('Пополнить источник выплат','Fund the payout source')}</h2><p>${pl('Только SRC-DEMO-FUND → SRC-DEMO-PM. Это собственные средства, а не доход и не погашение партнёрского долга. Автопополнение выключено.','Only SRC-DEMO-FUND → SRC-DEMO-PM. Own funds, not revenue or settlement of partner liabilities. Automatic funding is off.')}</p><form id="finance-transfer-form"><div class="support-filters">${supportSelect('finance-transfer-target',pl('Получатель','Target'),[['SRC-DEMO-PM','SRC-DEMO-PM · Polymarket']],d.target)}<div class="field"><label for="finance-transfer-amount">${pl('Сумма, USDT','Amount, USDT')}</label><input type="number" min="0.01" step="0.01" id="finance-transfer-amount" value="${escape(d.amount)}"></div><div class="field"><label for="finance-transfer-reason">${pl('Причина','Reason')}</label><input id="finance-transfer-reason" value="${escape(d.reason)}"></div></div><button class="btn" type="submit">${pl('Проверить пополнение','Review funding')}</button></form><p class="muted">${pl('Учебное правило ROUTE-FUND-v1: до 100 USDT — один владелец, выше — два; максимум получателя 1000 USDT. Комиссия 0,50 USDT за счёт исходного источника. Это не настройки реального сервиса.','Synthetic ROUTE-FUND-v1: up to 100 USDT requires one owner, above requires two; target maximum 1000 USDT. Fee 0.50 USDT paid by source. These are not real service settings.')}</p></section>${finance.transfers.map(x=>`<section class="panel"><h2>${x.id} · ${fstatus(x)}</h2><p>SRC-DEMO-FUND → SRC-DEMO-PM · v${x.sourceVersion} · ${fmoney(x.amount)} + ${fmoney(x.fee)}</p><p>${escape(x.reason)}</p><p>${pl('Резерв этой операции','This operation reserve')}: ${fmoney(['confirmed','failed'].includes(x.status)?0:x.amount+x.fee)} · ${pl('Свободно исходному источнику','Source free funds')}: ${fmoney(500-financeFundingUsed())}</p><p>${pl('Независимых подтверждений','Independent approvals')}: ${financeTransferApprovals(x).length} / ${x.required}</p><div class="actions">${['prepared','waiting','approved'].includes(x.status)?fbtn('Проверить личность · демо','Verify identity · demo','transfer-proof',`data-id="${x.id}"`)+fbtn('Подтвердить пополнение','Approve funding','transfer-approve',`data-id="${x.id}"`)+fbtn('Другой владелец: выйти и войти','Another owner: sign out and in','handoff'):''}${x.status==='approved'?fbtn('Выполнить учебное пополнение','Run synthetic funding','transfer-submit',`data-id="${x.id}"`):''}${x.status==='unknown'?fbtn('Сверить исходное пополнение','Reconcile original funding','transfer-reconcile',`data-id="${x.id}"`):''}</div><p>${x.status==='unknown'?pl('Повтор запрещён. Резерв сохраняется до подтверждённого итога.','Resubmission blocked. Reserve stays until a confirmed outcome.'):x.external||pl('Внешнее подтверждение ещё не получено','No external evidence yet')}</p></section>`).join('')}`;}
const financeFunded=()=> (finance.transfers||[]).filter(x=>x.status==='confirmed').reduce((s,x)=>s+x.amount,0);
const financeFundingUsed=()=> (finance.transfers||[]).filter(x=>x.status!=='failed').reduce((s,x)=>s+x.amount+x.fee,0);
const financeTransferDigest=x=>JSON.stringify([x.id,x.amount,x.reason,x.sourceVersion,finance.sourceVersion,finance.sourceActive,finance.block,x.required,x.fee,'SRC-DEMO-FUND','SRC-DEMO-PM','ROUTE-FUND-v1']);
const financeTransferApprovals=x=>x.approvals.filter(a=>a.expires>Date.now()&&a.digest===financeTransferDigest(x));
function financePrepareTransfer(){if(!financeAccess().write||fblocked())return false;finance.transfers??=[];const d=finance.transferDraft,amount=Number(d.amount);if(!Number.isFinite(amount)||amount<=0||d.target!=='SRC-DEMO-PM'||d.reason.trim().length<5||Math.abs(Math.round(amount*100)-amount*100)>0.000001){finance.error=['Укажите точную сумму с двумя десятичными знаками и причину от 5 символов.','Enter a positive amount with up to two decimals and a reason of at least 5 characters.'];return false;}const existing=finance.transfers.find(x=>x.status!=='failed'&&x.reason===d.reason.trim()&&x.amount===amount);if(existing){finance.notice=['Такая операция уже сохранена ниже. Повторный резерв не создан.','This operation is already listed below. No duplicate reserve was created.'];return true;}if(amount+0.5>500-financeFundingUsed()||finance.eligible+(finance.transfers||[]).filter(x=>x.status!=='failed').reduce((sum,x)=>sum+x.amount,0)+amount>Number(financeSourceConfig()?.hardMax||1000)){finance.error=['Не хватает свободных средств или превышен жёсткий максимум получателя.','Insufficient free source funds or the target hard maximum is exceeded.'];return false;}finance.transfers.push({id:'FUND-DEMO-'+(finance.transfers.length+1),amount,fee:0.5,reason:d.reason.trim(),sourceVersion:finance.sourceVersion,required:amount>100?2:1,status:'prepared',approvals:[]});flog('Подготовлено собственное пополнение','Own-source funding prepared');return true;}
function financeTransferAction(a,id){const x=finance.transfers?.find(x=>x.id===id);if(!financeAccess().write||!x)return false;const digest=financeTransferDigest(x),ready=['prepared','waiting','approved'].includes(x.status)&&!fblocked()&&x.sourceVersion===finance.sourceVersion;if(a==='transfer-proof'&&ready)finance.proof={id:actor().id,digest,expires:Date.now()+300000};else if(a==='transfer-approve'&&ready&&fproofValid(digest)&&!financeTransferApprovals(x).some(a=>a.id===actor().id)){x.approvals=financeTransferApprovals(x);x.approvals.push({id:actor().id,digest,expires:Date.now()+600000});finance.proof=null;x.status=x.approvals.length>=x.required?'approved':'waiting';}else if(a==='transfer-submit'&&ready&&x.status==='approved'&&financeTransferApprovals(x).length>=x.required){x.status=finance.outcome==='success'?'confirmed':finance.outcome==='failure'?'failed':'unknown';x.external=x.status==='confirmed'?'TX-DEMO-'+x.id:null;finance.proof=null;flog('Учебный исход собственного пополнения: '+x.status,'Synthetic own-source funding outcome: '+x.status);}else if(a==='transfer-reconcile'&&x.status==='unknown'){if(finance.outcome!=='unknown'){x.status=finance.outcome==='success'?'confirmed':'failed';x.external=x.status==='confirmed'?'TX-DEMO-'+x.id:null;}flog('Проверено исходное пополнение без повторной отправки','Original funding checked without resubmission');}else{finance.error=['Действие недоступно: проверьте версию, подтверждения и ограничения.','Unavailable: check version, approvals and restrictions.'];return false;}return true;}
document.addEventListener('input',e=>{if(e.target.id.startsWith('finance-transfer-')&&financeAccess().write){finance.transferDraft??={amount:'50',reason:'',target:'SRC-DEMO-PM'};finance.transferDraft[e.target.id.slice('finance-transfer-'.length)]=e.target.value;}});
document.addEventListener('submit',e=>{if(e.target.id==='finance-transfer-form'){e.preventDefault();finance.error=null;finance.notice=null;financePrepareTransfer();render();}});

function financeNewSources(){return Object.entries(finance.policies).filter(([k,p])=>k.startsWith('source:SRC-NEW-')&&p.history.length).map(([k,p])=>{const h=p.history.at(-1);return `<article class="support-notice"><h3>${escape(h.value)} · ${p.subject}</h3><p class="full-address">${escape(h.extra.sourceAddress)}</p><p>${escape(h.extra.network)} · ${escape(h.extra.asset)} · ${pl('Версия','Version')} ${h.version}</p><p>${h.extra.intent==='archive'?pl('Архивирован. История сохранена.','Archived. History retained.'):pl('Конфигурация согласована. Подтверждённых денежных данных и зарегистрированного маршрута пока нет; перевод недоступен.','Configuration approved. No confirmed monetary evidence or registered route yet; transfers unavailable.')}</p>${fbtn('Открыть конфигурацию','Open configuration','policy',`data-kind="source" data-source="${p.subject}"`)}</article>`;}).join('');}

function financeEnsureIncident(p){let x=incidents.records.find(i=>i.financePayout===p.id);if(x)return x;x={id:'INC-'+p.id,key:'finance',financePayout:p.id,uid:null,sid:null,ticket:null,name:financePartners.find(a=>a.id===p.partner).name,venue:p.venue,date:new Date(fnow()).toISOString().slice(0,10),priority:'high',status:'waiting',assignee:actor().id,title:['Неизвестен результат выплаты','Payout outcome unknown'],impact:['Повторная отправка выплаты запрещена. Резерв сохраняется.','Payout resubmission is blocked. Reserve is retained.'],fact:[p.id+' отправлена по сохранённому маршруту; итог не подтверждён.',p.id+' submitted on the retained route; outcome unconfirmed.'],missing:['Нужно подтверждение исходной операции, а не повторная отправка.','Original-operation evidence is required, not resubmission.'],restriction:['Закрытие инцидента не отправляет деньги и не снимает резерв.','Incident closure neither sends funds nor releases reserves.'],evidence:null,resolved:false,version:1,note:'',notes:[],events:[],closeReason:'',draft:null};incidents.records.push(x);return x;}
function financeIncidentLinks(x){const p=finance.payouts.find(p=>p.id===x.financePayout);return p?`<p>${p.id} · ${p.venue}</p>${fbtn('К исходной выплате и сверке','Original payout and reconciliation','incident-payout',`data-id="${p.id}"`)}<p>${pl('Сверка только подтверждает результат. Закрытие инцидента не выполняет повторную выплату.','Reconciliation only verifies the outcome. Incident closure does not repeat the payout.')}</p>`:'';}
